\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Venue Color Theme ──
\definecolor{primary}{HTML}{0A192F}     % deep navy
\definecolor{secondary}{HTML}{006D77}   % teal
\definecolor{accent}{HTML}{00B4D8}      % electric blue
\definecolor{bgposter}{HTML}{F4F7F9}    % tinted cool gray
\definecolor{redbg}{HTML}{F7F9FA}       % light slate
\definecolor{bluebg}{HTML}{F2F9FB}      % light cyan
\definecolor{darkbg}{HTML}{F3F5F7}      % light navy
\definecolor{redtitlebg}{HTML}{E8F1F3}
\definecolor{bluetitlebg}{HTML}{DDF2F6}
\definecolor{darktitlebg}{HTML}{E1E5ED}
\definecolor{textdark}{HTML}{1E293B}
\definecolor{textgray}{HTML}{475569}
\definecolor{stathighlight}{HTML}{FFFFFF}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=36pt, itemsep=12pt, parsep=4pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=36pt, itemsep=12pt, parsep=4pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[4mm]
  {\fontsize{20}{26}\selectfont\color{textgray}\textit{#3}}\vspace{3mm}%
}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={8pt}{0pt}{secondary},
    left=16pt, right=16pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={8pt}{0pt}{accent},
    left=16pt, right=16pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={8pt}{0pt}{primary},
    left=16pt, right=16pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={8pt}{0pt}{primary},
    left=16pt, right=16pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=24pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{64}{76}\selectfont\bfseries GLOBAL INTERNET USAGE}\\[16pt]
  {\fontsize{28}{34}\selectfont A Cross-Country Comparison of Digital Populations and Economies}\\[12pt]
  {\fontsize{22}{28}\selectfont\color{white!70} Data Report 2025 | Global Digital Economy Analysis}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=12pt, bottom=12pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{primary} $\sim$5.56B}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Global Internet Users}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{primary} $\sim$68\%}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Penetration Rate}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{primary} \$8.0T}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textdark} E-Commerce (2027)}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{primary} 143 min}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Daily Social Media}\vspace{10pt}%
    }}
  \end{minipage}
}

% ══ COL 1 ══
\posterbox[redcard, title={The World's Digital Population}
]{name=pop, column=1, between=row5 and row12}{
  \fontsize{26}{36}\selectfont
  The largest digital populations are concentrated in Asia, with \textbf{China and India} far ahead of other nations, forming a massive share of the global total.

  \vspace{24pt}
  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{p{0.45\linewidth} r}
    \rowcolor{primary!15} \textbf{Country} & \textbf{Online Population} \\
    China & $\sim$1.09 billion \\
    \rowcolor{black!5} India & $\sim$900 million \\
    United States & $\sim$320 million \\
    \rowcolor{black!5} Indonesia & $\sim$220 million \\
    Brazil & $\sim$190 million \\
  \end{tabular}

  \vspace{32pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \textbf{Insight:}\\
    China and India alone account for over \textbf{35\%} of the world's internet users, fundamentally shifting the global digital center of gravity.
  }}
}

\posterbox[bluecard, title={Internet Penetration Rates by Country}
]{name=penetration, column=1, between=row12 and bottom}{
  \fontsize{26}{36}\selectfont
  While Northern Europe and East Asia lead in total connectivity, vast opportunities remain in large developing regions.

  \vspace{24pt}
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{p{0.32\linewidth} r p{0.45\linewidth}}
    \rowcolor{accent!15} \textbf{Country} & \textbf{\%} & \textbf{Relative Scale} \\
    South Korea & 98 & \textcolor{accent}{\rule{0.98\linewidth}{14pt}} \\
    UK & 97 & \textcolor{accent}{\rule{0.97\linewidth}{14pt}} \\
    Germany & 96 & \textcolor{accent}{\rule{0.96\linewidth}{14pt}} \\
    Japan & 95 & \textcolor{accent}{\rule{0.95\linewidth}{14pt}} \\
    USA & 95 & \textcolor{accent}{\rule{0.95\linewidth}{14pt}} \\
    Brazil & 88 & \textcolor{accent}{\rule{0.88\linewidth}{14pt}} \\
    Indonesia & 78 & \textcolor{accent}{\rule{0.78\linewidth}{14pt}} \\
    \rowcolor{primary!15} China & 76 & \textcolor{primary}{\rule{0.76\linewidth}{14pt}} \\
    \rowcolor{primary!15} India & 62 & \textcolor{primary}{\rule{0.62\linewidth}{14pt}} \\
    Nigeria & 52 & \textcolor{accent}{\rule{0.52\linewidth}{14pt}} \\
  \end{tabular}

  \vspace{24pt}
  \begin{itemize}
    \item \textbf{High Access}: UK, Germany, and Japan sit at near-universal access ($>95\%$).
    \item \textbf{Room for Growth}: India and Nigeria have massive populations but lower penetration, representing the largest future growth vectors.
  \end{itemize}
}

% ══ COL 2 ══
\posterbox[darkcard, title={How People Spend Time Online}
]{name=usage, column=2, between=row5 and row11}{
  \fontsize{26}{36}\selectfont
  Daily social media usage continues its upward trajectory since 2012, now averaging \textbf{143 minutes globally}.

  \vspace{24pt}
  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{p{0.45\linewidth} r}
    \rowcolor{primary!15} \textbf{Platform} & \textbf{Active Users (MAU)} \\
    Facebook & $\sim$3.1 billion \\
    \rowcolor{black!5} YouTube & $\sim$2.5 billion \\
    WhatsApp & $\sim$2.4 billion \\
    \rowcolor{black!5} Instagram & $\sim$2.0 billion \\
    TikTok & $\sim$1.6 billion \\
  \end{tabular}

  \vspace{32pt}
  \begin{itemize}
    \item \textbf{Regional Variants}: Latin America and Southeast Asia show highest daily usage.
    \item \textbf{Lower Engagement}: Japan and Western Europe spend comparatively less time per day.
  \end{itemize}
}

\posterbox[highlightcard, title={The Digital Economy Impact}
]{name=economy, column=2, between=row11 and row17}{
  \fontsize{26}{36}\selectfont
  Internet infrastructure underpins explosive growth in retail and emerging technologies. The global AI market alone is forecast to scale from \$240B (2023) to \textbf{>\$800B by 2030}.

  \vspace{24pt}
  \colorbox{primary!30}{\parbox{0.94\linewidth}{%
    \textbf{E-commerce Dominance:}\\
    Online retail now exceeds \textbf{20\%} of all global retail sales, heavily reliant on mobile infrastructure.
  }}

  \vspace{24pt}
  \begin{itemize}
    \item \textbf{Mobile First}: Mobile traffic accounts for $>60\%$ of global web traffic.
    \item \textbf{Data Generation}: $>180$ zettabytes of data created globally by 2025.
  \end{itemize}
}

\posterbox[redcard, title={Key Takeaways}
]{name=takeaways, column=2, between=row17 and bottom}{
  \fontsize{26}{36}\selectfont
  \begin{enumerate}
    \item \textbf{Asian Dominance}: Asia leads in absolute user numbers, while Northern Europe and East Asia lead in total penetration.
    \item \textbf{Connectivity Gaps}: Sub-Saharan Africa and South Asia represent the largest remaining opportunities for network expansion.
    \item \textbf{Economic Engine}: The digital economy is expanding rapidly, with E-commerce and AI as the primary growth engines.
  \end{enumerate}
}

\end{tcbposter}
\end{document}
EOF
